export function attributeCalculationEditor(doc,index,files,hooks,edit,make){
 const row=doc.data.attributes[index],detail=make('details'),summary=make('summary',row.calculation?'종속 계산':'계산');detail.dataset.attributeCalculation=index;detail.append(summary);detail.open=doc.view?.abilityCalculation===index;detail.ontoggle=()=>{if(detail.open)(doc.view??={}).abilityCalculation=index;};
 const set=(key,value)=>edit(data=>data.attributes[index].calculation[key]=value),c=row.calculation;
 if(!c){const add=make('button','계산 추가');add.dataset.attributeCalculationAdd=index;add.onclick=()=>{(doc.view??={}).abilityCalculation=index;edit(data=>data.attributes[index].calculation={attribute:data.attributes.find((_,i)=>i!==index)?.name||(row.name==='Health'?'Mana':'Health'),policy:'current',coefficient:1,preAdd:0,postAdd:0,curve:'',track:''});};detail.append(add);return detail;}
 const form=make('div');form.className='attribute-calculation-form';const source=make('input');source.value=c.attribute;source.dataset.calculationField='attribute';source.setAttribute('aria-label','계산 원본 속성');source.onchange=()=>set('attribute',source.value);const label=make('label','원본 속성');label.append(source);form.append(label);
 const policy=make('select');policy.dataset.calculationField='policy';for(const[value,text]of[['current','현재값'],['base','기본값'],['bonus','보너스']]){const option=make('option',text);option.value=value;policy.append(option);}policy.value=c.policy;policy.onchange=()=>set('policy',policy.value);const pl=make('label','값');pl.append(policy);form.append(pl);
 for(const[key,text]of[['coefficient','계수'],['preAdd','계수 적용 전 더하기'],['postAdd','계수 적용 후 더하기']]){const label=make('label',text),input=make('input');input.type='number';input.step='any';input.value=c[key];input.dataset.calculationField=key;input.onchange=()=>set(key,Number(input.value));label.append(input);form.append(label);}
 const curve=make('select');curve.dataset.calculationField='curve';for(const file of[{path:'',name:'없음'},...files.filter(f=>f.kind==='curve'),...(c.curve&&!files.some(f=>f.path===c.curve)?[{path:c.curve,name:c.curve}]:[])]){const option=make('option',file.name);option.value=file.path;curve.append(option);}curve.value=c.curve;curve.onchange=async()=>{const before=JSON.stringify(doc.data),path=curve.value;try{const asset=path?await hooks.readAsset(path):null;if(!curve.isConnected||JSON.stringify(doc.data)!==before)return;edit(data=>Object.assign(data.attributes[index].calculation,{curve:path,track:asset?.timeline?.tracks.find(t=>t.type==='float')?.id||''}));}catch(error){hooks.error(error.message);}};const cl=make('label','커브');cl.append(curve);form.append(cl);
 if(c.curve){const track=make('input'),label=make('label','트랙 ID'),open=make('button','커브 열기');track.value=c.track;track.dataset.calculationField='track';track.onchange=()=>set('track',track.value);label.append(track);open.onclick=()=>hooks.openAsset?.(c.curve);form.append(label,open);}
 const remove=make('button','계산 제거');remove.dataset.attributeCalculationRemove=index;remove.onclick=()=>edit(data=>delete data.attributes[index].calculation);form.append(remove);detail.append(form);return detail;
}
